import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        long[] cnt = new long[26];
        byte[] buf = new byte[1 << 16];
        for (int k; (k = System.in.read(buf, 0, buf.length)) > 0; )
            for (int i = 0; i < k; i++) if (buf[i] >= 'a' && buf[i] <= 'z') cnt[buf[i] - 'a']++;
        int n = 0;
        for (long c : cnt) n += (int) c;
        // Fill from both ends in letter order; the single odd-count letter (if any) takes the center.
        byte[] out = new byte[n + 1];
        int l = 0, r = n - 1;
        for (int i = 0; i < 26; i++) {
            for (long k = 0; k < cnt[i] / 2; k++) {
                out[l++] = (byte) ('a' + i);
                out[r--] = (byte) ('a' + i);
            }
            if (cnt[i] % 2 == 1) out[n / 2] = (byte) ('a' + i);
        }
        out[n] = '\n';
        System.out.write(out);
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"os"
)

func main() {
	var cnt [26]int
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	buf := make([]byte, 1<<16)
	for {
		k, err := reader.Read(buf)
		for _, ch := range buf[:k] {
			if ch >= 'a' && ch <= 'z' {
				cnt[ch-'a']++
			}
		}
		if err != nil {
			break
		}
	}
	n := 0
	for _, c := range cnt {
		n += c
	}
	// Fill from both ends in letter order; the single odd-count letter (if any) takes the center.
	out := make([]byte, n+1)
	l, r := 0, n-1
	for i, c := range cnt {
		for k := 0; k < c/2; k++ {
			out[l], out[r] = byte('a'+i), byte('a'+i)
			l++
			r--
		}
		if c%2 == 1 {
			out[n/2] = byte('a' + i)
		}
	}
	out[n] = '\n'
	os.Stdout.Write(out)
}
